initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // 店舗選択肢を設定
  function populateStoreOptions() {
    const storeSelect = container.querySelector('#filter-store');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 精度データを生成（サンプルデータ）
  function generateAccuracyData() {
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const data = [];

    for (let i = 0; i < 20; i++) {
      const store = stores[Math.floor(Math.random() * stores.length)];
      const product = products[Math.floor(Math.random() * products.length)];
      const mape = (Math.random() * 30 + 5).toFixed(2);
      const rmse = (Math.random() * 20 + 5).toFixed(1);
      const accuracy = (100 - parseFloat(mape)).toFixed(1);

      data.push({
        id: `acc_${i + 1}`,
        rank: i + 1,
        store_id: store?.店舗ID || '',
        store_name: store?.店舗名 || `店舗${i + 1}`,
        product_id: product?.商品ID || '',
        product_name: product?.商品名 || `商品${i + 1}`,
        mape: parseFloat(mape),
        rmse: parseFloat(rmse),
        accuracy: parseFloat(accuracy),
        period: '過去30日'
      });
    }

    return data.sort((a, b) => a.mape - b.mape).map((item, index) => ({
      ...item,
      rank: index + 1
    }));
  }

  // 精度推移グラフを描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const days = 30;
    const mapeData = [];
    const rmseData = [];

    for (let i = 0; i < days; i++) {
      mapeData.push(15 + Math.sin(i * 0.2) * 3 + Math.random() * 2);
      rmseData.push(12 + Math.cos(i * 0.15) * 2 + Math.random() * 1.5);
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // MAPE線を描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < mapeData.length; i++) {
      const x = padding + (i / (mapeData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (mapeData[i] / 25) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // RMSE線を描画
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < rmseData.length; i++) {
      const x = padding + (i / (rmseData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (rmseData[i] / 20) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('MAPE', canvas.width - 150, 30);
    ctx.fillText('RMSE', canvas.width - 80, 30);

    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#10b981';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 100, 25);
    ctx.lineTo(canvas.width - 85, 25);
    ctx.stroke();
  }

  // 予測vs実績比較チャートを描画
  function drawForecastVsActualChart() {
    const canvas = container.querySelector('#forecast-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const days = 14;
    const forecastData = [];
    const actualData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.5) * 20;
      forecastData.push(base + Math.random() * 10);
      actualData.push(base + Math.random() * 15 - 5);
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測線を描画
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < forecastData.length; i++) {
      const x = padding + (i / (forecastData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (forecastData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 実績線を描画
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px Arial';
    ctx.fillText('予測値', canvas.width - 150, 30);
    ctx.fillText('実績値', canvas.width - 80, 30);

    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ef4444';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 100, 25);
    ctx.lineTo(canvas.width - 85, 25);
    ctx.stroke();
  }

  // テーブル再描画
  function renderAccuracyTable(data) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    tbody.innerHTML = data.map(row => {
      let accuracyClass = 'accuracy-medium';
      if (row.accuracy >= 85) accuracyClass = 'accuracy-high';
      else if (row.accuracy < 70) accuracyClass = 'accuracy-low';

      return `
        <tr data-id="${row.id}">
          <td>${row.rank}</td>
          <td>${row.store_name}</td>
          <td>${row.product_name}</td>
          <td>${row.mape.toFixed(2)}%</td>
          <td>${row.rmse.toFixed(1)}</td>
          <td class="${accuracyClass}">${row.accuracy.toFixed(1)}%</td>
          <td>${row.period}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[column];
      let bVal = b[column];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    // ソートアイコンを更新
    container.querySelectorAll('.sortable').forEach(th => {
      th.classList.remove('asc', 'desc');
      if (th.dataset.column === column) {
        th.classList.add(sortDirection);
      }
    });

    renderAccuracyTable(currentData);
  }

  // アラート表示
  function checkAccuracyAlerts(data) {
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');
    const threshold = 75; // 精度閾値

    const lowAccuracyItems = data.filter(item => item.accuracy < threshold);

    if (lowAccuracyItems.length > 0) {
      alertContent.innerHTML = `
        <p>以下の商品で予測精度が閾値(${threshold}%)を下回っています：</p>
        <ul>
          ${lowAccuracyItems.slice(0, 5).map(item => 
            `<li>${item.store_name} - ${item.product_name}: ${item.accuracy.toFixed(1)}%</li>`
          ).join('')}
          ${lowAccuracyItems.length > 5 ? `<li>他${lowAccuracyItems.length - 5}件</li>` : ''}
        </ul>
      `;
      alertPanel.classList.remove('hidden');
    } else {
      alertPanel.classList.add('hidden');
    }
  }

  // サマリー更新
  function updateSummary(data) {
    const avgMape = data.reduce((sum, item) => sum + item.mape, 0) / data.length;
    const avgRmse = data.reduce((sum, item) => sum + item.rmse, 0) / data.length;

    container.querySelector('#avg-mape').textContent = `${avgMape.toFixed(2)}%`;
    container.querySelector('#avg-rmse').textContent = avgRmse.toFixed(1);
    container.querySelector('#total-products').textContent = data.length;
  }

  // フィルター適用
  function applyFilters() {
    const period = container.querySelector('#filter-period').value;
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;

    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.store_id === storeId);
    }

    // カテゴリフィルターは簡易実装
    if (category) {
      filteredData = filteredData.filter(item => 
        item.product_name.includes(category) || Math.random() > 0.5
      );
    }

    renderAccuracyTable(filteredData);
    updateSummary(filteredData);
    checkAccuracyAlerts(filteredData);
  }

  // CSVエクスポート
  function exportToCsv() {
    const headers = ['順位', '店舗名', '商品名', 'MAPE(%)', 'RMSE', '精度(%)', '期間'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...currentData.map(row => [
        row.rank,
        `"${row.store_name}"`,
        `"${row.product_name}"`,
        row.mape.toFixed(2),
        row.rmse.toFixed(1),
        row.accuracy.toFixed(1),
        `"${row.period}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '予測精度レポート.csv';
    link.click();
  }

  // 初期化
  populateStoreOptions();
  currentData = generateAccuracyData();
  renderAccuracyTable(currentData);
  updateSummary(currentData);
  checkAccuracyAlerts(currentData);
  drawAccuracyTrendChart();
  drawForecastVsActualChart();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export-report').addEventListener('click', exportToCsv);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // ソート機能
  container.querySelectorAll('.sortable').forEach(th => {
    th.addEventListener('click', () => {
      sortData(th.dataset.column);
    });
  });

  // 詳細ボタン
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });
}
